import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Security and trust","description":"","frontmatter":{},"headers":[],"relativePath":"handl/explanation/security-and-trust.md","filePath":"vendored/handl/explanation/security-and-trust.md"}`),a={name:`handl/explanation/security-and-trust.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="security-and-trust" tabindex="-1">Security and trust <a class="header-anchor" href="#security-and-trust" aria-label="Permalink to “Security and trust”">​</a></h1><p>The handl platform is designed for trusted, curated plugin graphs. It does not provide sandboxing or permission manifests by default. This page explains the threat model and the practical limits of the design.</p><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to “Threat model”">​</a></h2><ul><li>All plugins run in the same process.</li><li>A plugin is a Rust crate or a dynamically loaded module.</li><li>A malicious or buggy plugin can compromise the entire process if it runs native code.</li><li>The platform does not provide process-level sandboxing by default.</li></ul><p>If you load a plugin, you are trusting it with the same privileges as the host process.</p><h2 id="what-the-design-gives-us" tabindex="-1">What the design gives us <a class="header-anchor" href="#what-the-design-gives-us" aria-label="Permalink to “What the design gives us”">​</a></h2><p>The platform does provide some safety properties:</p><ul><li><strong>Type-safe rule boundaries.</strong> <code>contribute::&lt;P&gt;(rule)</code> is checked at compile time. A <code>Format</code> rule cannot be contributed to a <code>Linter</code>.</li><li><strong>Explicit dependency declaration.</strong> <code>requires</code> and <code>optional</code> make the plugin graph visible and auditable.</li><li><strong>Closed kit manifests.</strong> A <code>Kit</code> lists every plugin it contains. The host is not surprised by hidden plugins.</li><li><strong>Option validation.</strong> <code>OptionSchema</code> declares <code>possible_values</code>. The <code>Options</code> plugin rejects values outside the declared set.</li><li><strong>Plugin exclusion.</strong> A <code>.handl.toml</code> can <code>exclude</code> specific plugins from a kit, so users can remove untrusted or experimental code.</li></ul><h2 id="what-the-design-does-not-give-us" tabindex="-1">What the design does not give us <a class="header-anchor" href="#what-the-design-does-not-give-us" aria-label="Permalink to “What the design does not give us”">​</a></h2><p>The design is not a security boundary for untrusted code:</p><ul><li><strong>No process isolation.</strong> A plugin that uses <code>unsafe</code> or calls arbitrary syscalls can crash or compromise the <code>Host</code>. Rust&#39;s type system does not prevent this.</li><li><strong>No automatic capability restrictions.</strong> By default, a <code>Plugin</code> can <code>contribute</code> to any <code>RuleAcceptor</code> and a <code>Library</code>/<code>Target</code> plugin can <code>register_plugin</code>.</li><li><strong>No plugin signing.</strong> Kits and libraries are trusted by inclusion, not by cryptographic signature.</li></ul><h2 id="recommended-security-measures" tabindex="-1">Recommended security measures <a class="header-anchor" href="#recommended-security-measures" aria-label="Permalink to “Recommended security measures”">​</a></h2><p>If you curate or deploy hosts, consider the following:</p><ol><li><p><strong>Capability-limited <code>ContributionContext</code>.</strong> The <code>Host</code> can hand different <code>ContributionContext</code> flavours to different plugins:</p><ul><li><code>Library</code> and <code>Target</code> plugins get <code>register_plugin</code>.</li><li>Rule plugins get <code>contribute</code> to public <code>RuleAcceptor</code>s only.</li><li>Untrusted plugins get a read-only or <code>contribute</code>-only context.</li></ul></li><li><p><strong>Trusted kit curation.</strong> <code>handl-kit-*</code> crates should be reviewed packages. A user <code>.handl.toml</code> should only pull from known kit crates or explicitly list direct plugins.</p></li><li><p><strong>No <code>unsafe</code> in canonical plugins.</strong> The <code>handl-platform</code> and <code>handl-plugin-ext-*</code> crates should be <code>#![forbid(unsafe_code)]</code> where possible.</p></li><li><p><strong>Reproducible, version-pinned kits.</strong> <code>Kit</code> manifests pin plugin versions. A host can refuse to load a kit whose dependency tree does not match the pinned hashes.</p></li></ol><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><p>Sandboxed targets, signed plugins, and permission manifests are not required for the initial design. They are tracked in <code>project/BACKLOG.md</code>.</p><p>The design is <strong>safe for trusted, curated plugin graphs</strong> and <strong>not safe for arbitrary untrusted native plugins</strong>. If you need untrusted third-party plugins, use a sandboxed <code>Target</code> or an external sandbox.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};